part of 'academy_english_advanced_models.dart';
abstract final class EnglishA2UnitTwoDialogues {
  static const items = <String,EnglishAdvancedDialogue>{
'a2.2.1':EnglishAdvancedDialogue(lines:<String>["Mariam: Is this small room yours?","Housemate: No, it is hers. Yours is upstairs.","Mariam: Is the wardrobe mine?","Housemate: Yes, the wardrobe is yours.","Mariam: Thanks. I will arrange my books tonight."],tip:"Possessive pronouns – practice each example aloud.",tipArabic:"نستعمل mine وyours بدل تكرار الاسم: This room is mine. ونستعمل my وyour قبل الأسماء.",pronunciation:<String>["roommate /ˈruːmmeɪt/","wardrobe /ˈwɔːrdroʊb/","curtain /ˈkɝːtən/"]),
'a2.2.2':EnglishAdvancedDialogue(lines:<String>["Patient: I feel dizzy and tired.","Nurse: You should rest today.","Patient: Should I go to work tomorrow?","Nurse: Not if you still have a fever.","Patient: Thank you. I will stay home."],tip:"Should and shouldn't – practice each example aloud.",tipArabic:"نستخدم should للنصيحة وshouldn't لما يجب تجنبه، ويأتي بعدها الفعل دون to.",pronunciation:<String>["dizzy /ˈdɪzi/","symptom /ˈsɪmptəm/","fever /ˈfiːvər/"]),
'a2.2.3':EnglishAdvancedDialogue(lines:<String>["Leena: How much rice should I use?","Grandmother: Use a little more than one cup.","Leena: Do we need a few tomatoes?","Grandmother: Yes, and enough water for the rice.","Leena: I'll taste the sauce before serving."],tip:"Quantifiers: a little and a few – practice each example aloud.",tipArabic:"نستخدم a little مع غير المعدود مثل rice، وa few مع المعدود مثل tomatoes؛ وenough للكمية الكافية.",pronunciation:<String>["cinnamon /ˈsɪnəmən/","cumin /ˈkuːmɪn/","saucepan /ˈsɔːspæn/"]),
'a2.2.4':EnglishAdvancedDialogue(lines:<String>["Yusuf: Do I have to replace the wheel?","Mechanic: No, you don't have to.","Yusuf: Can I ride home now?","Mechanic: You mustn't ride before I test the brakes.","Yusuf: Thank you for checking everything."],tip:"Mustn't versus don't have to – practice each example aloud.",tipArabic:"نستخدم mustn't للمنع وdon't have to لعدم الضرورة. يأتي بعد الأفعال المساعدة الفعل الأساسي.",pronunciation:<String>["mechanic /məˈkænɪk/","bicycle /ˈbaɪsɪkəl/","pressure /ˈprɛʃər/"]),
'a2.2.5':EnglishAdvancedDialogue(lines:<String>["Salma: Could you tell me about this kitten?","Volunteer: Certainly. She is playful but gentle.","Salma: Can she stay inside our apartment?","Volunteer: Yes, with toys and a safe space.","Salma: I will prepare everything at home."],tip:"Can and could for polite requests – practice each example aloud.",tipArabic:"نستخدم can للسؤال عن الإذن، وcould لصياغة طلب ألطف؛ ولا نضيف to بعدهما.",pronunciation:<String>["kitten /ˈkɪtən/","adoption /əˈdɑːpʃən/","vaccination /ˌvæksəˈneɪʃən/"]),
'a2.2.6':EnglishAdvancedDialogue(lines:<String>["Host: Would you like to come for tea?","Hala: I'd love to. When should I arrive?","Host: At four. Shall I send directions?","Hala: Yes, please. I'll bring biscuits.","Host: Wonderful. See you on Saturday!"],tip:"Would you like to for invitations – practice each example aloud.",tipArabic:"ندعو الآخرين باستخدام Would you like to ...? ونوافق بأسلوب لطيف بـ I'd love to.",pronunciation:<String>["invitation /ˌɪnvɪˈteɪʃən/","teapot /ˈtiːpɑːt/","host /hoʊst/"]),
'a2.2.7':EnglishAdvancedDialogue(lines:<String>["Partner: Have you ever joined a language exchange?","Omar: No, I have never tried one.","Partner: What do you want to practice?","Omar: I want to speak more confidently.","Partner: Great. Let's ask short questions."],tip:"Present perfect: ever and never – practice each example aloud.",tipArabic:"نسأل عن الخبرة باستخدام Have you ever... ونستخدم I have never... للتعبير عن تجربة لم تحدث من قبل.",pronunciation:<String>["exchange /ɪksˈtʃeɪndʒ/","fluency /ˈfluːənsi/","phrase /freɪz/"]),
'a2.2.8':EnglishAdvancedDialogue(lines:<String>["Reem: Have you found a black phone yet?","Officer: Someone has just handed one in.","Reem: I have already checked my bag.","Officer: Please describe its phone case.","Reem: It has a blue sticker."],tip:"Present perfect with just and already – practice each example aloud.",tipArabic:"نستخدم have/has + التصريف الثالث مع just وalready للحدث الأخير المرتبط بالحاضر.",pronunciation:<String>["device /dɪˈvaɪs/","conductor /kənˈdʌktər/","notification /ˌnoʊtɪfɪˈkeɪʃən/"]),
'a2.2.9':EnglishAdvancedDialogue(lines:<String>["Amal: Is the key ring cheaper than the wallet?","Assistant: Yes, and it is more personal.","Amal: Can you add my brother's initials?","Assistant: Of course. Would you like gift wrapping?","Amal: Yes, please. What is the total?"],tip:"Comparatives with more, less and as...as – practice each example aloud.",tipArabic:"نستخدم more وless للمقارنة، وas ... as للمساواة بين شيئين.",pronunciation:<String>["personalized /ˈpɝːsənəlaɪzd/","receipt /rɪˈsiːt/","engraving /ɪnˈɡreɪvɪŋ/"]),
'a2.2.10':EnglishAdvancedDialogue(lines:<String>["Friend: Are we going to visit the lighthouse?","Guide: Yes, but the path is windy.","Friend: Will the boat trip happen today?","Guide: It will if the sea becomes calm.","Friend: Great. We will bring jackets."],tip:"Going to and will for future plans – practice each example aloud.",tipArabic:"نستخدم going to لخطط قررناها مسبقًا، وwill للقرارات أو التوقعات التي نعلنها الآن.",pronunciation:<String>["coastal /ˈkoʊstəl/","lighthouse /ˈlaɪthaʊs/","itinerary /aɪˈtɪnərɛri/"])
  };
}
